(function() {
  const CELL = 20;
  const MAP = [
    "############################",
    "#............##............#",
    "#.####.#####.##.#####.####.#",
    "#o####.#####.##.#####.####o#",
    "#.####.#####.##.#####.####.#",
    "#..........................#",
    "#.####.##.########.##.####.#",
    "#.####.##.########.##.####.#",
    "#......##....##....##......#",
    "######.##### ## #####.######",
    "     #.##### ## #####.#     ",
    "     #.##          ##.#     ",
    "     #.## ###--### ##.#     ",
    "######.## #      # ##.######",
    "      .   #      #   .      ",
    "######.## #      # ##.######",
    "     #.## ######## ##.#     ",
    "     #.##          ##.#     ",
    "     #.## ######## ##.#     ",
    "######.## ######## ##.######",
    "#............##............#",
    "#.####.#####.##.#####.####.#",
    "#.####.#####.##.#####.####.#",
    "#o..##.......  .......##..o#",
    "###.##.##.########.##.##.###",
    "###.##.##.########.##.##.###",
    "#......##....##....##......#",
    "#.##########.##.##########.#",
    "#.##########.##.##########.#",
    "#..........................#",
    "############################"
  ];

  const ROWS = MAP.length;
  const COLS = MAP[0].length;
  const WIDTH = COLS * CELL;
  const HEIGHT = ROWS * CELL;

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const scoreEl = document.getElementById('score');
  const highscoreEl = document.getElementById('highscore');
  const livesEl = document.getElementById('lives');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const startBtn = document.getElementById('startBtn');

  let grid = [];
  let totalDots = 0;
  let dotsEaten = 0;
  let score = 0;
  let highScore = parseInt(localStorage.getItem('pacmanHigh') || '0');
  let lives = 3;
  let gameRunning = false;
  let animFrame = null;
  let frightTimer = 0;
  let frightDuration = 300;

  highscoreEl.textContent = highScore;

  const WALL = 0;
  const DOT = 1;
  const EMPTY = 2;
  const POWER = 3;
  const GHOST_DOOR = 4;

  function buildGrid() {
    grid = [];
    totalDots = 0;
    dotsEaten = 0;
    for (let r = 0; r < ROWS; r++) {
      grid[r] = [];
      for (let c = 0; c < COLS; c++) {
        const ch = MAP[r][c];
        if (ch === '#') grid[r][c] = WALL;
        else if (ch === '.') { grid[r][c] = DOT; totalDots++; }
        else if (ch === 'o') { grid[r][c] = POWER; totalDots++; }
        else if (ch === '-') grid[r][c] = GHOST_DOOR;
        else grid[r][c] = EMPTY;
      }
    }
  }

  function isWall(r, c) {
    if (r < 0 || r >= ROWS) return true;
    if (c < 0 || c >= COLS) return false; // tunnel
    return grid[r][c] === WALL;
  }

  function canMove(r, c, isGhost) {
    if (c < 0 || c >= COLS) return true; // tunnel
    if (r < 0 || r >= ROWS) return false;
    if (grid[r][c] === WALL) return false;
    if (grid[r][c] === GHOST_DOOR && !isGhost) return false;
    return true;
  }

  const pacman = { r: 23, c: 14, dir: 'left', nextDir: 'left', mouthOpen: 0, mouthDir: 1 };

  function resetPacman() {
    pacman.r = 23;
    pacman.c = 14;
    pacman.dir = 'left';
    pacman.nextDir = 'left';
  }

  const ghostColors = ['#FF0000', '#FFB8FF', '#00FFFF', '#FFB852'];
  const ghostNames = ['blinky', 'pinky', 'inky', 'clyde'];
  let ghosts = [];

  function createGhosts() {
    ghosts = [
      { r: 13, c: 13, dir: 'left', color: ghostColors[0], name: ghostNames[0], frightened: false, eaten: false, homeTimer: 0 },
      { r: 13, c: 14, dir: 'up', color: ghostColors[1], name: ghostNames[1], frightened: false, eaten: false, homeTimer: 60 },
      { r: 13, c: 15, dir: 'up', color: ghostColors[2], name: ghostNames[2], frightened: false, eaten: false, homeTimer: 120 },
      { r: 14, c: 14, dir: 'up', color: ghostColors[3], name: ghostNames[3], frightened: false, eaten: false, homeTimer: 180 }
    ];
  }

  function resetGhosts() {
    createGhosts();
  }

  const dirs = {
    'up': { dr: -1, dc: 0 },
    'down': { dr: 1, dc: 0 },
    'left': { dr: 0, dc: -1 },
    'right': { dr: 0, dc: 1 }
  };

  const opposite = { 'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left' };

  let moveCounter = 0;
  let ghostMoveCounter = 0;
  const pacSpeed = 4;
  const ghostSpeed = 5;

  function drawWalls() {
    ctx.fillStyle = '#1e3a8a';
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (grid[r][c] === WALL) {
          const x = c * CELL;
          const y = r * CELL;
          ctx.fillRect(x, y, CELL, CELL);

          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 1;

          if (r > 0 && grid[r-1] && grid[r-1][c] !== WALL) {
            ctx.beginPath(); ctx.moveTo(x, y + 0.5); ctx.lineTo(x + CELL, y + 0.5); ctx.stroke();
          }
          if (r < ROWS - 1 && grid[r+1] && grid[r+1][c] !== WALL) {
            ctx.beginPath(); ctx.moveTo(x, y + CELL - 0.5); ctx.lineTo(x + CELL, y + CELL - 0.5); ctx.stroke();
          }
          if (c > 0 && grid[r][c-1] !== WALL) {
            ctx.beginPath(); ctx.moveTo(x + 0.5, y); ctx.lineTo(x + 0.5, y + CELL); ctx.stroke();
          }
          if (c < COLS - 1 && grid[r][c+1] !== WALL) {
            ctx.beginPath(); ctx.moveTo(x + CELL - 0.5, y); ctx.lineTo(x + CELL - 0.5, y + CELL); ctx.stroke();
          }
        }
      }
    }
  }

  function drawDots() {
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = c * CELL + CELL / 2;
        const y = r * CELL + CELL / 2;
        if (grid[r][c] === DOT) {
          ctx.fillStyle = '#fde68a';
          ctx.beginPath();
          ctx.arc(x, y, 2, 0, Math.PI * 2);
          ctx.fill();
        } else if (grid[r][c] === POWER) {
          ctx.fillStyle = '#fde68a';
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, Math.PI * 2);
          ctx.fill();
        } else if (grid[r][c] === GHOST_DOOR) {
          ctx.fillStyle = '#FFB8FF';
          ctx.fillRect(c * CELL, r * CELL + CELL / 2 - 2, CELL, 4);
        }
      }
    }
  }

  function drawPacman() {
    const x = pacman.c * CELL + CELL / 2;
    const y = pacman.r * CELL + CELL / 2;
    const radius = CELL / 2 - 1;

    pacman.mouthOpen += 0.15 * pacman.mouthDir;
    if (pacman.mouthOpen > 1) { pacman.mouthOpen = 1; pacman.mouthDir = -1; }
    if (pacman.mouthOpen < 0) { pacman.mouthOpen = 0; pacman.mouthDir = 1; }

    const mouthAngle = pacman.mouthOpen * 0.4;
    let startAngle = mouthAngle;
    let endAngle = Math.PI * 2 - mouthAngle;

    let rotation = 0;
    if (pacman.dir === 'right') rotation = 0;
    else if (pacman.dir === 'down') rotation = Math.PI / 2;
    else if (pacman.dir === 'left') rotation = Math.PI;
    else if (pacman.dir === 'up') rotation = -Math.PI / 2;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rotation);
    ctx.fillStyle = '#FACC15';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.arc(0, 0, radius, startAngle, endAngle);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawGhost(ghost) {
    const x = ghost.r < 0 ? ghost.c * CELL + CELL / 2 : ghost.c * CELL + CELL / 2;
    const y = ghost.r * CELL + CELL / 2;
    const r = CELL / 2 - 1;

    if (ghost.eaten) {
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(x - 3, y - 2, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(x + 3, y - 2, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x - 3, y - 2, 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(x + 3, y - 2, 1.5, 0, Math.PI * 2);
      ctx.fill();
      return;
    }

    let color = ghost.color;
    if (ghost.frightened) {
      color = frightTimer < 60 && Math.floor(frightTimer / 8) % 2 === 0 ? '#fff' : '#2563eb';
    }

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y - 2, r, Math.PI, 0, false);
    ctx.lineTo(x + r, y + r - 2);

    const waveCount = 3;
    const waveWidth = (r * 2) / waveCount;
    for (let i = 0; i < waveCount; i++) {
      const bx = x + r - waveWidth * i;
      const by = y + r - 2;
      ctx.quadraticCurveTo(bx - waveWidth * 0.25, by + 4, bx - waveWidth * 0.5, by);
      ctx.quadraticCurveTo(bx - waveWidth * 0.75, by - 4, bx - waveWidth, by);
    }

    ctx.closePath();
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(x - 3, y - 3, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x + 3, y - 3, 3, 0, Math.PI * 2);
    ctx.fill();

    if (!ghost.frightened) {
      const d = dirs[ghost.dir];
      const ex = d.dc * 1.5;
      const ey = d.dr * 1.5;
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x - 3 + ex, y - 3 + ey, 1.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(x + 3 + ex, y - 3 + ey, 1.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function wrapCol(c) {
    if (c < 0) return COLS - 1;
    if (c >= COLS) return 0;
    return c;
  }

  function movePacman() {
    moveCounter++;
    if (moveCounter < pacSpeed) return;
    moveCounter = 0;

    // Try next direction first
    const nd = dirs[pacman.nextDir];
    const nr = pacman.r + nd.dr;
    const nc = wrapCol(pacman.c + nd.dc);
    if (canMove(nr, nc, false)) {
      pacman.dir = pacman.nextDir;
      pacman.r = nr;
      pacman.c = nc;
    } else {
      const cd = dirs[pacman.dir];
      const cr = pacman.r + cd.dr;
      const cc = wrapCol(pacman.c + cd.dc);
      if (canMove(cr, cc, false)) {
        pacman.r = cr;
        pacman.c = cc;
      }
    }

    // Check dot eating
    if (pacman.r >= 0 && pacman.r < ROWS && pacman.c >= 0 && pacman.c < COLS) {
      if (grid[pacman.r][pacman.c] === DOT) {
        grid[pacman.r][pacman.c] = EMPTY;
        score += 10;
        dotsEaten++;
      } else if (grid[pacman.r][pacman.c] === POWER) {
        grid[pacman.r][pacman.c] = EMPTY;
        score += 50;
        dotsEaten++;
        frightTimer = frightDuration;
        ghosts.forEach(g => {
          if (!g.eaten) g.frightened = true;
        });
      }
      scoreEl.textContent = score;
    }
  }

  function getGhostTarget(ghost) {
    if (ghost.eaten) {
      return { r: 13, c: 14 };
    }
    if (ghost.frightened) {
      return { r: Math.floor(Math.random() * ROWS), c: Math.floor(Math.random() * COLS) };
    }

    switch(ghost.name) {
      case 'blinky':
        return { r: pacman.r, c: pacman.c };
      case 'pinky': {
        const d = dirs[pacman.dir];
        return { r: pacman.r + d.dr * 4, c: pacman.c + d.dc * 4 };
      }
      case 'inky': {
        const d = dirs[pacman.dir];
        const ahead = { r: pacman.r + d.dr * 2, c: pacman.c + d.dc * 2 };
        const blinky = ghosts[0];
        return { r: ahead.r + (ahead.r - blinky.r), c: ahead.c + (ahead.c - blinky.c) };
      }
      case 'clyde': {
        const dist = Math.abs(ghost.r - pacman.r) + Math.abs(ghost.c - pacman.c);
        if (dist > 8) return { r: pacman.r, c: pacman.c };
        return { r: ROWS - 1, c: 0 };
      }
      default:
        return { r: pacman.r, c: pacman.c };
    }
  }

  function moveGhosts() {
    ghostMoveCounter++;
    const speed = frightTimer > 0 ? ghostSpeed + 3 : ghostSpeed;
    if (ghostMoveCounter < speed) return;
    ghostMoveCounter = 0;

    ghosts.forEach(ghost => {
      if (ghost.homeTimer > 0) {
        ghost.homeTimer--;
        return;
      }

      const target = getGhostTarget(ghost);
      const possibleDirs = ['up', 'down', 'left', 'right'].filter(d => {
        if (d === opposite[ghost.dir]) return false;
        const dd = dirs[d];
        const nr = ghost.r + dd.dr;
        const nc = wrapCol(ghost.c + dd.dc);
        return canMove(nr, nc, true);
      });

      if (possibleDirs.length === 0) {
        // Reverse if stuck
        const dd = dirs[opposite[ghost.dir]];
        const nr = ghost.r + dd.dr;
        const nc = wrapCol(ghost.c + dd.dc);
        if (canMove(nr, nc, true)) {
          ghost.dir = opposite[ghost.dir];
          ghost.r = nr;
          ghost.c = nc;
        }
        return;
      }

      let bestDir = possibleDirs[0];
      let bestDist = Infinity;

      possibleDirs.forEach(d => {
        const dd = dirs[d];
        const nr = ghost.r + dd.dr;
        const nc = wrapCol(ghost.c + dd.dc);
        const dist = (nr - target.r) ** 2 + (nc - target.c) ** 2;
        if (dist < bestDist) {
          bestDist = dist;
          bestDir = d;
        }
      });

      if (ghost.frightened) {
        bestDir = possibleDirs[Math.floor(Math.random() * possibleDirs.length)];
      }

      ghost.dir = bestDir;
      const dd = dirs[bestDir];
      ghost.r = ghost.r + dd.dr;
      ghost.c = wrapCol(ghost.c + dd.dc);

      if (ghost.eaten && ghost.r === 13 && (ghost.c === 13 || ghost.c === 14)) {
        ghost.eaten = false;
        ghost.frightened = false;
      }
    });
  }

  function checkCollisions() {
    ghosts.forEach(ghost => {
      if (ghost.homeTimer > 0) return;
      if (ghost.r === pacman.r && ghost.c === pacman.c) {
        if (ghost.frightened && !ghost.eaten) {
          ghost.eaten = true;
          ghost.frightened = false;
          score += 200;
          scoreEl.textContent = score;
        } else if (!ghost.eaten) {
          lives--;
          livesEl.textContent = lives;
          if (lives <= 0) {
            gameOver();
          } else {
            resetPacman();
            resetGhosts();
          }
        }
      }
    });
  }

  function checkWin() {
    if (dotsEaten >= totalDots) {
      winGame();
    }
  }

  function gameOver() {
    gameRunning = false;
    if (score > highScore) {
      highScore = score;
      localStorage.setItem('pacmanHigh', highScore.toString());
      highscoreEl.textContent = highScore;
    }
    overlayTitle.textContent = 'GAME OVER';
    overlayText.textContent = 'Final score: ' + score;
    startBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
  }

  function winGame() {
    gameRunning = false;
    if (score > highScore) {
      highScore = score;
      localStorage.setItem('pacmanHigh', highScore.toString());
      highscoreEl.textContent = highScore;
    }
    overlayTitle.textContent = 'YOU WIN!';
    overlayText.textContent = 'Congratulations! Score: ' + score;
    startBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
  }

  function draw() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    drawWalls();
    drawDots();
    drawPacman();
    ghosts.forEach(drawGhost);
  }

  function update() {
    if (!gameRunning) return;

    movePacman();
    moveGhosts();
    checkCollisions();
    checkWin();

    if (frightTimer > 0) {
      frightTimer--;
      if (frightTimer <= 0) {
        ghosts.forEach(g => { g.frightened = false; });
      }
    }
  }

  function gameLoop() {
    update();
    draw();
    animFrame = requestAnimationFrame(gameLoop);
  }

  function startGame() {
    buildGrid();
    resetPacman();
    createGhosts();
    score = 0;
    lives = 3;
    frightTimer = 0;
    moveCounter = 0;
    ghostMoveCounter = 0;
    scoreEl.textContent = '0';
    livesEl.textContent = '3';
    overlay.classList.add('hidden');
    gameRunning = true;
    if (animFrame) cancelAnimationFrame(animFrame);
    gameLoop();
  }

  startBtn.addEventListener('click', startGame);

  document.addEventListener('keydown', function(e) {
    switch(e.key) {
      case 'ArrowUp': case 'w': case 'W':
        e.preventDefault();
        pacman.nextDir = 'up'; break;
      case 'ArrowDown': case 's': case 'S':
        e.preventDefault();
        pacman.nextDir = 'down'; break;
      case 'ArrowLeft': case 'a': case 'A':
        e.preventDefault();
        pacman.nextDir = 'left'; break;
      case 'ArrowRight': case 'd': case 'D':
        e.preventDefault();
        pacman.nextDir = 'right'; break;
    }
  });

  // Mobile dpad
  document.querySelectorAll('.dpad-btn').forEach(btn => {
    const handler = (e) => {
      e.preventDefault();
      const dir = btn.getAttribute('data-dir');
      if (dir) pacman.nextDir = dir;
    };
    btn.addEventListener('touchstart', handler, { passive: false });
    btn.addEventListener('mousedown', handler);
  });

  // Initial draw
  buildGrid();
  draw();

  // Responsive canvas
  function resizeCanvas() {
    const container = document.querySelector('.game-container');
    const maxW = Math.min(window.innerWidth - 48, 1100);
    const scale = Math.min(maxW / WIDTH, 1);
    canvas.style.width = (WIDTH * scale) + 'px';
    canvas.style.height = (HEIGHT * scale) + 'px';
  }

  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);
})();

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  background: #0f172a;
  color: #f8fafc;
  line-height: 1.65;
  font-size: 1rem;
  min-height: 100vh;
  overflow-x: hidden;
}

.nav {
  position: sticky;
  top: 0;
  height: 64px;
  background: #1e293b;
  border-bottom: 1px solid #334155;
  z-index: 100;
  display: flex;
  align-items: center;
}

.nav-inner {
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  gap: 32px;
}

.logo {
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  color: #FACC15;
  margin-right: auto;
}

.score-display, .lives-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
}

.score-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #94a3b8;
  font-weight: 600;
}

.score-value {
  font-size: 1.1rem;
  font-weight: 800;
  color: #f8fafc;
  font-variant-numeric: tabular-nums;
}

.main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 40px 24px 80px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.game-container {
  position: relative;
  background: #000;
  border-radius: 12px;
  border: 1px solid #334155;
  box-shadow: 0 4px 24px rgba(0,0,0,0.5);
  overflow: hidden;
}

#gameCanvas {
  display: block;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.overlay.hidden {
  display: none;
}

.overlay-content {
  text-align: center;
  padding: 40px;
}

.overlay-content h2 {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  color: #FACC15;
  margin-bottom: 16px;
}

.overlay-content p {
  color: #94a3b8;
  margin-bottom: 32px;
  font-size: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 32px;
  background: #FACC15;
  color: #0f172a;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: #EAB308;
}

.btn:active {
  transform: scale(0.97);
}

.controls-mobile {
  display: none;
  margin-top: 24px;
}

.dpad {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.dpad-middle {
  display: flex;
  align-items: center;
  gap: 4px;
}

.dpad-btn {
  width: 60px;
  height: 60px;
  min-height: 44px;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  color: #f8fafc;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

.dpad-btn:active {
  background: #334155;
}

.dpad-center {
  width: 60px;
  height: 60px;
}

@media (max-width: 768px) {
  .nav-inner {
    gap: 16px;
    padding: 0 16px;
  }

  .main {
    padding: 24px 16px 40px;
  }

  .controls-mobile {
    display: flex;
  }
}
